/* =========================================================================
 * BackgroundImage — official underwater gameplay background (backgroundGame.png).
 *
 * Inlined as a data URI so the game stays ONE self-contained HTML file. Shown
 * full-screen via CSS `cover` on the #stage container (fills every device size,
 * preserves aspect, crops only the outer edges, no stretch, no overlay/tint).
 * The single DATA string is referenced by both CSS (set at runtime) and the
 * optional canvas draw, so it is stored only once.
 * ========================================================================= */
const BackgroundImage = (() => {
  const DATA = 'data:image/png;base64,';
  let img = null, ready = false;
  function load() {
    if (typeof Image === 'undefined') { ready = true; return Promise.resolve(); }
    return new Promise((res) => {
      img = new Image();
      img.onload = () => { ready = true; res(); };
      img.onerror = () => { ready = true; res(); };
      img.src = DATA;
    });
  }
  return { DATA, load, image: () => (img && img.complete && img.naturalWidth > 0 ? img : null), isReady: () => ready };
})();
